private RewardedAd openMobileRewardedAd = null;
private boolean openMobileRewardedAdLoading = false;
private boolean openMobileRewardedAdsInitialized = false;
private static final int OPEN_MOBILE_DATA_PROCESSING_STANDARD = 2;
private static final int OPEN_MOBILE_DATA_PROCESSING_RESTRICTED = 3;
private boolean openMobileRewardedAdsInitializing = false;
private InitializationStatus openMobileRewardedAdsInitializationStatus = null;
private long openMobileActiveFullscreenShowRequestId = 0;
private final Map<Long, InterstitialAd> openMobileLoadedInterstitialAds =
    new HashMap<>();
private final Set<Long> openMobileInterstitialAdLoadRequests = new HashSet<>();
private final Map<Long, AppOpenAd> openMobileLoadedAppOpenAds =
    new HashMap<>();
private final Set<Long> openMobileAppOpenAdLoadRequests = new HashSet<>();
private final Map<Long, RewardedAd> openMobileLoadedRewardedAds = new HashMap<>();
private final Set<Long> openMobileRewardedAdLoadRequests = new HashSet<>();
private final Map<Long, RewardedInterstitialAd>
    openMobileLoadedRewardedInterstitialAds = new HashMap<>();
private final Set<Long> openMobileRewardedInterstitialAdLoadRequests =
    new HashSet<>();
private static final int OPEN_MOBILE_BANNER_TOP = 0;
private static final int OPEN_MOBILE_BANNER_CENTER = 2;
private static final int OPEN_MOBILE_HORIZONTAL_LEFT = 0;
private static final int OPEN_MOBILE_HORIZONTAL_RIGHT = 2;
private static final int OPEN_MOBILE_DISPLAY_FIXED_BANNER = 0;
private static final int OPEN_MOBILE_DISPLAY_ADAPTIVE_BANNER = 1;
private static final int OPEN_MOBILE_DISPLAY_MREC = 2;
private static final class OpenMobileBannerEntry
{
    final long loadRequestId;
    final String adUnitId;
    final int displayFormat;
    AdView adView = null;
    FrameLayout container = null;
    long showRequestId = 0;
    int anchor = OPEN_MOBILE_BANNER_TOP;
    int horizontalAlignment = 1;
    boolean respectSafeArea = true;
    float availableWidth = 0.0f;
    float leftMargin = 0.0f;
    float topMargin = 0.0f;
    float rightMargin = 0.0f;
    float bottomMargin = 0.0f;
    int loadedWidth = 0;
    int loadedHeight = 0;
    boolean initialLoadComplete = false;
    boolean bannerReady = false;
    boolean notifyShownAfterLoad = false;

    OpenMobileBannerEntry(
        long inLoadRequestId,
        String inAdUnitId,
        int inDisplayFormat
    )
    {
        loadRequestId = inLoadRequestId;
        adUnitId = inAdUnitId;
        displayFormat = inDisplayFormat;
    }
}
private final Map<Long, OpenMobileBannerEntry> openMobileBannerAds =
    new HashMap<>();

