private String openMobileAdsLoadErrorCode(LoadAdError error)
{
    if (error == null)
    {
        return "internal_error";
    }
    switch (error.getCode())
    {
    case 1:
        return "invalid_request";
    case 2:
        return "network_error";
    case 3:
    case 9:
        return "no_fill";
    case 8:
        return "missing_app_id";
    default:
        return "internal_error";
    }
}

private void dispatchOpenMobileRevenuePaid(
    boolean banner,
    long requestId,
    AdValue adValue,
    ResponseInfo responseInfo
)
{
    AdapterResponseInfo source = responseInfo == null
        ? null
        : responseInfo.getLoadedAdapterResponseInfo();
    String sourceName = source == null ? null : source.getAdSourceName();
    String sourceId = source == null ? null : source.getAdSourceId();
    String adapterClassName = source == null ? null : source.getAdapterClassName();
    String instanceName = source == null ? null : source.getAdSourceInstanceName();
    String instanceId = source == null ? null : source.getAdSourceInstanceId();
    if (banner)
    {
        nativeOpenMobileBannerAdRevenuePaid(
            requestId,
            adValue.getValueMicros(),
            adValue.getCurrencyCode(),
            adValue.getPrecisionType(),
            sourceName,
            sourceId,
            adapterClassName,
            instanceName,
            instanceId
        );
        return;
    }

    nativeOpenMobileRewardedAdRevenuePaid(
        requestId,
        adValue.getValueMicros(),
        adValue.getCurrencyCode(),
        adValue.getPrecisionType(),
        sourceName,
        sourceId,
        adapterClassName,
        instanceName,
        instanceId
    );
}

private int openMobileDensityPixels(float value)
{
    return Math.round(value * getResources().getDisplayMetrics().density);
}

private void detachOpenMobileBanner(
    OpenMobileBannerEntry entry,
    boolean clearShowRequest
)
{
    if (entry.container != null)
    {
        entry.container.setOnApplyWindowInsetsListener(null);
        ViewParent parent = entry.container.getParent();
        if (parent instanceof ViewGroup)
        {
            ((ViewGroup) parent).removeView(entry.container);
        }
        entry.container.removeAllViews();
        entry.container = null;
    }
    if (clearShowRequest)
    {
        entry.showRequestId = 0;
        entry.notifyShownAfterLoad = false;
    }
}

private void destroyOpenMobileBannerView(OpenMobileBannerEntry entry)
{
    if (entry.adView != null)
    {
        entry.adView.setAdListener(null);
        entry.adView.setOnPaidEventListener(null);
        entry.adView.destroy();
        entry.adView = null;
    }
}

private void destroyOpenMobileBanner(OpenMobileBannerEntry entry)
{
    detachOpenMobileBanner(entry, true);
    destroyOpenMobileBannerView(entry);
}

private int resolveOpenMobileAdaptiveWidth(
    OpenMobileBannerEntry entry,
    WindowInsets windowInsets
)
{
    View decorView = GameActivity.this.getWindow().getDecorView();
    int availablePixels = decorView.getWidth();
    if (availablePixels <= 0)
    {
        availablePixels = getResources().getDisplayMetrics().widthPixels;
    }
    if (entry.respectSafeArea && windowInsets != null)
    {
        int safeLeft = windowInsets.getSystemWindowInsetLeft();
        int safeRight = windowInsets.getSystemWindowInsetRight();
        if (Build.VERSION.SDK_INT >= 28 && windowInsets.getDisplayCutout() != null)
        {
            safeLeft = Math.max(
                safeLeft,
                windowInsets.getDisplayCutout().getSafeInsetLeft()
            );
            safeRight = Math.max(
                safeRight,
                windowInsets.getDisplayCutout().getSafeInsetRight()
            );
        }
        availablePixels -= safeLeft + safeRight;
    }
    availablePixels -= openMobileDensityPixels(
        entry.leftMargin + entry.rightMargin
    );
    int availableDp = (int) Math.floor(
        availablePixels / getResources().getDisplayMetrics().density
    );
    if (entry.availableWidth > 0.0f)
    {
        availableDp = Math.min(
            availableDp,
            (int) Math.floor(entry.availableWidth)
        );
    }
    if (availableDp < 320)
    {
        throw new IllegalStateException(
            "The Android safe area and margins cannot fit an adaptive banner."
        );
    }
    return availableDp;
}

private AdSize resolveOpenMobileBannerAdSize(
    OpenMobileBannerEntry entry,
    WindowInsets windowInsets
)
{
    if (entry.displayFormat == OPEN_MOBILE_DISPLAY_MREC)
    {
        return AdSize.MEDIUM_RECTANGLE;
    }
    if (entry.displayFormat != OPEN_MOBILE_DISPLAY_ADAPTIVE_BANNER)
    {
        return AdSize.BANNER;
    }
    return AdSize.getLargeAnchoredAdaptiveBannerAdSize(
        GameActivity.this,
        resolveOpenMobileAdaptiveWidth(entry, windowInsets)
    );
}

private boolean hasOpenMobileBannerSize(
    OpenMobileBannerEntry entry,
    AdSize adSize
)
{
    return entry.loadedWidth == adSize.getWidth()
        && entry.loadedHeight == adSize.getHeight();
}

private void loadOpenMobileBannerView(
    final OpenMobileBannerEntry entry,
    final AdSize adSize
)
{
    destroyOpenMobileBannerView(entry);
    entry.bannerReady = false;
    final AdView adView = new AdView(GameActivity.this);
    entry.adView = adView;
    entry.loadedWidth = adSize.getWidth();
    entry.loadedHeight = adSize.getHeight();
    adView.setAdSize(adSize);
    adView.setAdUnitId(entry.adUnitId);
    adView.setAdListener(new AdListener()
    {
        @Override
        public void onAdLoaded()
        {
            if (
                openMobileBannerAds.get(entry.loadRequestId) != entry
                || entry.adView != adView
            )
            {
                return;
            }
            entry.bannerReady = true;
            if (!entry.initialLoadComplete)
            {
                entry.initialLoadComplete = true;
                nativeOpenMobileBannerAdLoadCompleted(entry.loadRequestId);
                return;
            }
            if (entry.showRequestId != 0)
            {
                try
                {
                    attachOpenMobileBanner(entry);
                }
                catch (Exception exception)
                {
                    final long failedShowRequestId = entry.showRequestId;
                    openMobileBannerAds.remove(entry.loadRequestId);
                    destroyOpenMobileBanner(entry);
                    nativeOpenMobileBannerAdOperationFailed(
                        failedShowRequestId,
                        "Adaptive banner could not be attached: "
                            + exception.getMessage()
                    );
                    return;
                }
                if (entry.notifyShownAfterLoad)
                {
                    entry.notifyShownAfterLoad = false;
                    nativeOpenMobileBannerAdShown(entry.showRequestId);
                }
            }
        }

        @Override
        public void onAdFailedToLoad(LoadAdError loadAdError)
        {
            if (
                openMobileBannerAds.get(entry.loadRequestId) != entry
                || entry.adView != adView
            )
            {
                return;
            }
            final boolean initialLoadFailed = !entry.initialLoadComplete;
            if (initialLoadFailed)
            {
                openMobileBannerAds.remove(entry.loadRequestId);
                destroyOpenMobileBanner(entry);
                nativeOpenMobileBannerAdLoadFailed(
                    entry.loadRequestId,
                    openMobileAdsLoadErrorCode(loadAdError),
                    "Banner failed to load: " + loadAdError.getMessage()
                );
            }
            else if (entry.showRequestId != 0)
            {
                final long failedShowRequestId = entry.showRequestId;
                openMobileBannerAds.remove(entry.loadRequestId);
                destroyOpenMobileBanner(entry);
                nativeOpenMobileBannerAdOperationFailed(
                    failedShowRequestId,
                    "Adaptive banner failed to resize: "
                        + loadAdError.getMessage()
                );
            }
            else
            {
                destroyOpenMobileBannerView(entry);
            }
        }

        @Override
        public void onAdImpression()
        {
            if (entry.showRequestId != 0)
            {
                nativeOpenMobileBannerAdImpression(entry.showRequestId);
            }
        }

        @Override
        public void onAdClicked()
        {
            if (entry.showRequestId != 0)
            {
                nativeOpenMobileBannerAdClicked(entry.showRequestId);
            }
        }
    });
    adView.setOnPaidEventListener(new OnPaidEventListener()
    {
        @Override
        public void onPaidEvent(AdValue adValue)
        {
            if (entry.showRequestId != 0)
            {
                dispatchOpenMobileRevenuePaid(
                    true,
                    entry.showRequestId,
                    adValue,
                    entry.adView.getResponseInfo()
                );
            }
        }
    });
    adView.loadAd(new AdRequest.Builder().build());
}

private boolean canOpenMobileBannerFit(
    OpenMobileBannerEntry entry,
    WindowInsets windowInsets
)
{
    int safeLeft = 0;
    int safeTop = 0;
    int safeRight = 0;
    int safeBottom = 0;
    if (entry.respectSafeArea && windowInsets != null)
    {
        safeLeft = windowInsets.getSystemWindowInsetLeft();
        safeTop = windowInsets.getSystemWindowInsetTop();
        safeRight = windowInsets.getSystemWindowInsetRight();
        safeBottom = windowInsets.getSystemWindowInsetBottom();
        if (Build.VERSION.SDK_INT >= 28 && windowInsets.getDisplayCutout() != null)
        {
            safeLeft = Math.max(
                safeLeft,
                windowInsets.getDisplayCutout().getSafeInsetLeft()
            );
            safeTop = Math.max(
                safeTop,
                windowInsets.getDisplayCutout().getSafeInsetTop()
            );
            safeRight = Math.max(
                safeRight,
                windowInsets.getDisplayCutout().getSafeInsetRight()
            );
            safeBottom = Math.max(
                safeBottom,
                windowInsets.getDisplayCutout().getSafeInsetBottom()
            );
        }
    }

    View decorView = GameActivity.this.getWindow().getDecorView();
    int availableWidth = decorView.getWidth();
    int availableHeight = decorView.getHeight();
    if (availableWidth <= 0)
    {
        availableWidth = getResources().getDisplayMetrics().widthPixels;
    }
    if (availableHeight <= 0)
    {
        availableHeight = getResources().getDisplayMetrics().heightPixels;
    }
    availableWidth -= safeLeft + safeRight + openMobileDensityPixels(
        entry.leftMargin + entry.rightMargin
    );
    availableHeight -= safeTop + safeBottom + openMobileDensityPixels(
        entry.topMargin + entry.bottomMargin
    );
    AdSize currentSize = entry.adView == null ? null : entry.adView.getAdSize();
    return currentSize != null
        && availableWidth >= currentSize.getWidthInPixels(GameActivity.this)
        && availableHeight >= currentSize.getHeightInPixels(GameActivity.this);
}

private void applyOpenMobileBannerLayout(
    final OpenMobileBannerEntry entry,
    WindowInsets windowInsets
)
{
    if (entry.container == null)
    {
        return;
    }
    if (
        entry.displayFormat == OPEN_MOBILE_DISPLAY_ADAPTIVE_BANNER
        && entry.showRequestId != 0
    )
    {
        try
        {
            AdSize desiredSize = resolveOpenMobileBannerAdSize(entry, windowInsets);
            if (!hasOpenMobileBannerSize(entry, desiredSize))
            {
                detachOpenMobileBanner(entry, false);
                entry.notifyShownAfterLoad = false;
                loadOpenMobileBannerView(entry, desiredSize);
                return;
            }
        }
        catch (Exception exception)
        {
            final long failedShowRequestId = entry.showRequestId;
            openMobileBannerAds.remove(entry.loadRequestId);
            destroyOpenMobileBanner(entry);
            nativeOpenMobileBannerAdOperationFailed(
                failedShowRequestId,
                "Adaptive banner could not resize: " + exception.getMessage()
            );
            return;
        }
    }
    if (!canOpenMobileBannerFit(entry, windowInsets))
    {
        final long failedShowRequestId = entry.showRequestId;
        openMobileBannerAds.remove(entry.loadRequestId);
        destroyOpenMobileBanner(entry);
        nativeOpenMobileBannerAdOperationFailed(
            failedShowRequestId,
            "The Android safe area and margins cannot fit the ad."
        );
        return;
    }

    int safeLeft = 0;
    int safeTop = 0;
    int safeRight = 0;
    int safeBottom = 0;
    if (entry.respectSafeArea && windowInsets != null)
    {
        safeLeft = windowInsets.getSystemWindowInsetLeft();
        safeTop = windowInsets.getSystemWindowInsetTop();
        safeRight = windowInsets.getSystemWindowInsetRight();
        safeBottom = windowInsets.getSystemWindowInsetBottom();
        if (Build.VERSION.SDK_INT >= 28 && windowInsets.getDisplayCutout() != null)
        {
            safeLeft = Math.max(
                safeLeft,
                windowInsets.getDisplayCutout().getSafeInsetLeft()
            );
            safeTop = Math.max(
                safeTop,
                windowInsets.getDisplayCutout().getSafeInsetTop()
            );
            safeRight = Math.max(
                safeRight,
                windowInsets.getDisplayCutout().getSafeInsetRight()
            );
            safeBottom = Math.max(
                safeBottom,
                windowInsets.getDisplayCutout().getSafeInsetBottom()
            );
        }
    }

    int containerHeight = entry.anchor == OPEN_MOBILE_BANNER_CENTER
        ? ViewGroup.LayoutParams.MATCH_PARENT
        : ViewGroup.LayoutParams.WRAP_CONTENT;
    int containerGravity = entry.anchor == OPEN_MOBILE_BANNER_TOP
        ? Gravity.TOP
        : entry.anchor == OPEN_MOBILE_BANNER_CENTER
            ? Gravity.CENTER_VERTICAL
            : Gravity.BOTTOM;
    FrameLayout.LayoutParams containerLayout = new FrameLayout.LayoutParams(
        ViewGroup.LayoutParams.MATCH_PARENT,
        containerHeight,
        containerGravity
    );
    containerLayout.leftMargin = safeLeft + openMobileDensityPixels(entry.leftMargin);
    containerLayout.topMargin = safeTop + openMobileDensityPixels(entry.topMargin);
    containerLayout.rightMargin = safeRight + openMobileDensityPixels(entry.rightMargin);
    containerLayout.bottomMargin = safeBottom + openMobileDensityPixels(entry.bottomMargin);
    entry.container.setLayoutParams(containerLayout);

}

private void attachOpenMobileBanner(final OpenMobileBannerEntry entry)
{
    if (entry.adView == null || !entry.bannerReady)
    {
        throw new IllegalStateException("The Android banner view is unavailable.");
    }
    WindowInsets windowInsets = GameActivity.this.getWindow()
        .getDecorView().getRootWindowInsets();
    if (!canOpenMobileBannerFit(entry, windowInsets))
    {
        throw new IllegalStateException(
            "The Android safe area and margins cannot fit the ad."
        );
    }
    final FrameLayout container = new FrameLayout(GameActivity.this)
    {
        @Override
        protected void onSizeChanged(int width, int height, int oldWidth, int oldHeight)
        {
            super.onSizeChanged(width, height, oldWidth, oldHeight);
            requestApplyInsets();
        }
    };
    int horizontalGravity = entry.horizontalAlignment == OPEN_MOBILE_HORIZONTAL_LEFT
        ? Gravity.LEFT
        : entry.horizontalAlignment == OPEN_MOBILE_HORIZONTAL_RIGHT
            ? Gravity.RIGHT
            : Gravity.CENTER_HORIZONTAL;
    int verticalGravity = entry.anchor == OPEN_MOBILE_BANNER_CENTER
        ? Gravity.CENTER_VERTICAL
        : Gravity.TOP;
    FrameLayout.LayoutParams bannerLayout = new FrameLayout.LayoutParams(
        ViewGroup.LayoutParams.WRAP_CONTENT,
        ViewGroup.LayoutParams.WRAP_CONTENT,
        horizontalGravity | verticalGravity
    );
    container.addView(entry.adView, bannerLayout);
    entry.container = container;
    container.setOnApplyWindowInsetsListener(new View.OnApplyWindowInsetsListener()
    {
        @Override
        public WindowInsets onApplyWindowInsets(View view, WindowInsets windowInsets)
        {
            applyOpenMobileBannerLayout(entry, windowInsets);
            return windowInsets;
        }
    });
    GameActivity.this.addContentView(
        container,
        new ViewGroup.LayoutParams(
            ViewGroup.LayoutParams.MATCH_PARENT,
            entry.anchor == OPEN_MOBILE_BANNER_CENTER
                ? ViewGroup.LayoutParams.MATCH_PARENT
                : ViewGroup.LayoutParams.WRAP_CONTENT
        )
    );
    applyOpenMobileBannerLayout(entry, container.getRootWindowInsets());
    container.requestApplyInsets();
}

private void reportOpenMobileAdsAdapterInitializationStatuses(
    long requestId,
    InitializationStatus initializationStatus
)
{
    if (initializationStatus == null)
    {
        return;
    }
    for (Map.Entry<String, AdapterStatus> entry
        : initializationStatus.getAdapterStatusMap().entrySet())
    {
        AdapterStatus status = entry.getValue();
        if (status == null)
        {
            continue;
        }
        nativeOpenMobileAdsAdapterInitializationStatus(
            requestId,
            entry.getKey(),
            status.getInitializationState() == AdapterStatus.State.READY,
            status.getLatency(),
            status.getDescription()
        );
    }
}

private int normalizeOpenMobileUMPPrivacyOptions(
    ConsentInformation consentInformation
)
{
    switch (consentInformation.getPrivacyOptionsRequirementStatus())
    {
        case NOT_REQUIRED:
            return 1;
        case REQUIRED:
            return 2;
        default:
            return 0;
    }
}

private String normalizeOpenMobileUMPErrorCode(FormError error)
{
    if (error == null)
    {
        return "ump_internal";
    }
    switch (error.getErrorCode())
    {
        case 2:
            return "ump_network";
        case 3:
            return "ump_invalid_operation";
        case 4:
            return "ump_timeout";
        default:
            return "ump_internal";
    }
}

public boolean AndroidThunkJava_RequestOpenMobileUMPConsent(
    final long requestId,
    final boolean underAgeOfConsent,
    final String[] testDeviceIdentifiers,
    final int debugGeography
)
{
    try
    {
        GameActivity.this.runOnUiThread(new Runnable()
        {
            @Override
            public void run()
            {
                try
                {
                    ConsentRequestParameters.Builder parameters =
                        new ConsentRequestParameters.Builder()
                            .setTagForUnderAgeOfConsent(underAgeOfConsent);
                    if (testDeviceIdentifiers != null
                        && testDeviceIdentifiers.length > 0)
                    {
                        ConsentDebugSettings.Builder debugSettings =
                            new ConsentDebugSettings.Builder(GameActivity.this);
                        for (String identifier : testDeviceIdentifiers)
                        {
                            debugSettings.addTestDeviceHashedId(identifier);
                        }
                        switch (debugGeography)
                        {
                            case 1:
                                debugSettings.setDebugGeography(
                                    ConsentDebugSettings.DebugGeography.DEBUG_GEOGRAPHY_EEA
                                );
                                break;
                            case 2:
                                debugSettings.setDebugGeography(
                                    ConsentDebugSettings.DebugGeography.DEBUG_GEOGRAPHY_REGULATED_US_STATE
                                );
                                break;
                            case 3:
                                debugSettings.setDebugGeography(
                                    ConsentDebugSettings.DebugGeography.DEBUG_GEOGRAPHY_OTHER
                                );
                                break;
                            default:
                                debugSettings.setDebugGeography(
                                    ConsentDebugSettings.DebugGeography.DEBUG_GEOGRAPHY_DISABLED
                                );
                                break;
                        }
                        parameters.setConsentDebugSettings(debugSettings.build());
                    }
                    final ConsentInformation consentInformation =
                        UserMessagingPlatform.getConsentInformation(GameActivity.this);
                    consentInformation.requestConsentInfoUpdate(
                        GameActivity.this,
                        parameters.build(),
                        () -> nativeOpenMobileUMPConsentInfoUpdated(
                            requestId,
                            consentInformation.getConsentStatus(),
                            consentInformation.canRequestAds(),
                            normalizeOpenMobileUMPPrivacyOptions(consentInformation)
                        ),
                        error -> nativeOpenMobileUMPConsentFailed(
                            requestId,
                            normalizeOpenMobileUMPErrorCode(error),
                            error != null ? error.getMessage() : "Unknown UMP request error."
                        )
                    );
                }
                catch (Exception exception)
                {
                    nativeOpenMobileUMPConsentFailed(
                        requestId,
                        "ump_internal",
                        exception.getMessage()
                    );
                }
            }
        });
        return true;
    }
    catch (Exception exception)
    {
        Log.error("OpenMobile UMP request could not be scheduled: " + exception.getMessage());
        return false;
    }
}

