public boolean AndroidThunkJava_InitializeOpenMobileRewardedAds(
    final long requestId,
    final int childDirectedTreatment,
    final int underAgeOfConsent,
    final String[] testDeviceIdentifiers,
    final String maxAdContentRating
)
{
    try
    {
        GameActivity.this.runOnUiThread(new Runnable()
        {
            @Override
            public void run()
            {
                try
                {
                    RequestConfiguration.Builder configuration =
                        MobileAds.getRequestConfiguration().toBuilder()
                            .setTagForChildDirectedTreatment(childDirectedTreatment)
                            .setTagForUnderAgeOfConsent(underAgeOfConsent)
                            .setTestDeviceIds(Arrays.asList(testDeviceIdentifiers));
                    if (maxAdContentRating != null && maxAdContentRating.length() > 0)
                    {
                        configuration.setMaxAdContentRating(maxAdContentRating);
                    }
                    MobileAds.setRequestConfiguration(configuration.build());

                    if (openMobileRewardedAdsInitialized)
                    {
                        reportOpenMobileAdsAdapterInitializationStatuses(
                            requestId,
                            openMobileRewardedAdsInitializationStatus
                        );
                        nativeOpenMobileAdsInitializationCompleted(requestId);
                        return;
                    }
                    if (openMobileRewardedAdsInitializing)
                    {
                        nativeOpenMobileAdsInitializationFailed(
                            requestId,
                            "AdMob SDK initialization is already in progress."
                        );
                        return;
                    }

                    openMobileRewardedAdsInitializing = true;
                    MobileAds.initialize(activityContext, new OnInitializationCompleteListener()
                    {
                        @Override
                        public void onInitializationComplete(InitializationStatus initializationStatus)
                        {
                            openMobileRewardedAdsInitializing = false;
                            openMobileRewardedAdsInitialized = true;
                            openMobileRewardedAdsInitializationStatus = initializationStatus;
                            Log.debug("OpenMobile rewarded Google ads initialized");
                            reportOpenMobileAdsAdapterInitializationStatuses(
                                requestId,
                                initializationStatus
                            );
                            nativeOpenMobileAdsInitializationCompleted(requestId);
                        }
                    });
                }
                catch (Exception exception)
                {
                    openMobileRewardedAdsInitializing = false;
                    nativeOpenMobileAdsInitializationFailed(
                        requestId,
                        "AdMob SDK initialization failed: " + exception.getMessage()
                    );
                }
            }
        });
        return true;
    }
    catch (Exception exception)
    {
        Log.error("OpenMobile AdMob initialization could not be scheduled: " + exception.getMessage());
        return false;
    }
}

public void AndroidThunkJava_ShutdownOpenMobileRewardedAds()
{
    GameActivity.this.runOnUiThread(new Runnable()
    {
        @Override
        public void run()
        {
            for (OpenMobileBannerEntry entry : openMobileBannerAds.values())
            {
                destroyOpenMobileBanner(entry);
            }
            openMobileBannerAds.clear();
            openMobileRewardedAd = null;
            openMobileRewardedAdLoading = false;
            openMobileActiveFullscreenShowRequestId = 0;
            openMobileLoadedInterstitialAds.clear();
            openMobileInterstitialAdLoadRequests.clear();
            openMobileLoadedAppOpenAds.clear();
            openMobileAppOpenAdLoadRequests.clear();
            openMobileLoadedRewardedAds.clear();
            openMobileRewardedAdLoadRequests.clear();
            openMobileLoadedRewardedInterstitialAds.clear();
            openMobileRewardedInterstitialAdLoadRequests.clear();
        }
    });
}

private void applyOpenMobileDataProcessingMode(final int dataProcessingMode)
{
    if (dataProcessingMode == OPEN_MOBILE_DATA_PROCESSING_RESTRICTED)
    {
        PreferenceManager.getDefaultSharedPreferences(activityContext)
            .edit().putInt("gad_rdp", 1).apply();
    }
    else if (dataProcessingMode == OPEN_MOBILE_DATA_PROCESSING_STANDARD)
    {
        PreferenceManager.getDefaultSharedPreferences(activityContext)
            .edit().remove("gad_rdp").apply();
    }
}

public boolean AndroidThunkJava_ResetOpenMobileUMPConsent()
{
    try
    {
        boolean preferencesCleared = PreferenceManager
            .getDefaultSharedPreferences(activityContext)
            .edit().remove("gad_rdp").commit();
        if (!preferencesCleared)
        {
            Log.error("OpenMobile could not clear AdMob data-processing state.");
            return false;
        }
        UserMessagingPlatform.getConsentInformation(activityContext).reset();
        if (UserMessagingPlatform.getConsentInformation(activityContext)
            .getConsentStatus() != ConsentInformation.ConsentStatus.UNKNOWN)
        {
            Log.error("OpenMobile UMP consent state did not reset to unknown.");
            return false;
        }
        return true;
    }
    catch (Exception exception)
    {
        Log.error("OpenMobile UMP consent reset failed: " + exception.getMessage());
        return false;
    }
}

public boolean AndroidThunkJava_ApplyOpenMobileAdsConsentSignals(
    final int dataProcessingMode
)
{
    try
    {
        applyOpenMobileDataProcessingMode(dataProcessingMode);
        return true;
    }
    catch (Exception exception)
    {
        Log.error("OpenMobile consent signals could not be applied: " + exception.getMessage());
        return false;
    }
}

public boolean AndroidThunkJava_LoadOpenMobileRewardedAd(
    final String adUnitId,
    final long requestId,
    final int dataProcessingMode
)
{
    try
    {
        GameActivity.this.runOnUiThread(new Runnable()
        {
            @Override
            public void run()
            {
                if (adUnitId == null || adUnitId.trim().length() == 0)
                {
                    nativeOpenMobileRewardedAdLoadFailed(
                        requestId,
                        "invalid_request",
                        "The Android rewarded ad unit ID is empty."
                    );
                    return;
                }
                if (
                    openMobileRewardedAdLoadRequests.contains(requestId)
                    || openMobileLoadedRewardedAds.containsKey(requestId)
                )
                {
                    nativeOpenMobileRewardedAdLoadFailed(
                        requestId,
                        "invalid_state",
                        "The Android rewarded load request is already active."
                    );
                    return;
                }

                openMobileRewardedAdLoadRequests.add(requestId);
                applyOpenMobileDataProcessingMode(dataProcessingMode);
                try
                {
                    RewardedAd.load(
                        activityContext,
                        adUnitId,
                        new AdRequest.Builder().build(),
                        new RewardedAdLoadCallback()
                        {
                            @Override
                            public void onAdLoaded(RewardedAd rewardedAd)
                            {
                                if (!openMobileRewardedAdLoadRequests.remove(requestId))
                                {
                                    return;
                                }
                                openMobileLoadedRewardedAds.put(requestId, rewardedAd);
                                nativeOpenMobileRewardedAdLoadCompleted(requestId);
                            }

                            @Override
                            public void onAdFailedToLoad(LoadAdError loadAdError)
                            {
                                if (!openMobileRewardedAdLoadRequests.remove(requestId))
                                {
                                    return;
                                }
                                nativeOpenMobileRewardedAdLoadFailed(
                                    requestId,
                                    openMobileAdsLoadErrorCode(loadAdError),
                                    "Rewarded ad failed to load: " + loadAdError.getMessage()
                                );
                            }
                        }
                    );
                }
                catch (Exception exception)
                {
                    openMobileRewardedAdLoadRequests.remove(requestId);
                    nativeOpenMobileRewardedAdLoadFailed(
                        requestId,
                        "internal_error",
                        "Rewarded ad load could not start: " + exception.getMessage()
                    );
                }
            }
        });
        return true;
    }
    catch (Exception exception)
    {
        Log.error("OpenMobile rewarded ad load failed: " + exception.getMessage());
        return false;
    }
}

public void AndroidThunkJava_CancelOpenMobileRewardedAdLoad(final long requestId)
