                        "The Android rewarded-interstitial load request is already active."
                    );
                    return;
                }

                openMobileRewardedInterstitialAdLoadRequests.add(requestId);
                applyOpenMobileDataProcessingMode(dataProcessingMode);
                try
                {
                    RewardedInterstitialAd.load(
                        activityContext,
