                        new RewardedInterstitialAdLoadCallback()
                        {
                            @Override
                            public void onAdLoaded(
                                RewardedInterstitialAd rewardedInterstitialAd
                            )
                            {
                                if (
                                    !openMobileRewardedInterstitialAdLoadRequests
                                        .remove(requestId)
                                )
                                {
                                    return;
                                }
                                openMobileLoadedRewardedInterstitialAds.put(
                                    requestId,
                                    rewardedInterstitialAd
                                );
                                RewardItem rewardItem =
                                    rewardedInterstitialAd.getRewardItem();
                                nativeOpenMobileRewardedInterstitialAdLoadCompleted(
                                    requestId,
                                    rewardItem == null ? 0 : rewardItem.getAmount(),
                                    rewardItem == null ? "" : rewardItem.getType()
                                );
                            }

                            @Override
                            public void onAdFailedToLoad(LoadAdError loadAdError)
                            {
                                if (
                                    !openMobileRewardedInterstitialAdLoadRequests
                                        .remove(requestId)
                                )
                                {
                                    return;
                                }
                                nativeOpenMobileRewardedInterstitialAdLoadFailed(
                                    requestId,
                                    openMobileAdsLoadErrorCode(loadAdError),
                                    "Rewarded interstitial failed to load: "
                                        + loadAdError.getMessage()
                                );
                            }
                        }
                    );
                }
                catch (Exception exception)
                {
                    openMobileRewardedInterstitialAdLoadRequests.remove(requestId);
                    nativeOpenMobileRewardedInterstitialAdLoadFailed(
                        requestId,
                        "internal_error",
                        "Rewarded-interstitial load could not start: "
                            + exception.getMessage()
                    );
                }
            }
        });
        return true;
    }
    catch (Exception exception)
    {
        Log.error(
            "OpenMobile rewarded-interstitial load failed: "
                + exception.getMessage()
        );
        return false;
    }
}

