public boolean AndroidThunkJava_LoadOpenMobileBannerAd(
    final String adUnitId,
    final long requestId,
    final int dataProcessingMode,
    final int displayFormat,
    final int anchor,
    final int horizontalAlignment,
    final boolean respectSafeArea,
    final float availableWidth,
    final float leftMargin,
    final float topMargin,
    final float rightMargin,
    final float bottomMargin
)
{
    try
    {
        GameActivity.this.runOnUiThread(new Runnable()
        {
            @Override
            public void run()
            {
                if (adUnitId == null || adUnitId.trim().length() == 0)
                {
                    nativeOpenMobileBannerAdLoadFailed(
                        requestId,
                        "invalid_request",
                        "The Android banner ad unit ID is empty."
                    );
                    return;
                }
                if (openMobileBannerAds.containsKey(requestId))
                {
                    nativeOpenMobileBannerAdLoadFailed(
                        requestId,
                        "invalid_state",
                        "The Android banner load request is already active."
                    );
                    return;
                }

                applyOpenMobileDataProcessingMode(dataProcessingMode);
                try
                {
                    final OpenMobileBannerEntry entry = new OpenMobileBannerEntry(
                        requestId,
                        adUnitId,
                        displayFormat
                    );
                    entry.anchor = anchor;
                    entry.horizontalAlignment = horizontalAlignment;
                    entry.respectSafeArea = respectSafeArea;
                    entry.availableWidth = availableWidth;
                    entry.leftMargin = leftMargin;
                    entry.topMargin = topMargin;
                    entry.rightMargin = rightMargin;
                    entry.bottomMargin = bottomMargin;
                    openMobileBannerAds.put(requestId, entry);
                    WindowInsets windowInsets = GameActivity.this.getWindow()
                        .getDecorView().getRootWindowInsets();
                    loadOpenMobileBannerView(
                        entry,
                        resolveOpenMobileBannerAdSize(entry, windowInsets)
                    );
                }
                catch (Exception exception)
                {
                    OpenMobileBannerEntry entry = openMobileBannerAds.remove(requestId);
                    if (entry != null)
                    {
                        destroyOpenMobileBanner(entry);
                    }
                    nativeOpenMobileBannerAdLoadFailed(
                        requestId,
                        "internal_error",
                        "Banner load could not start: " + exception.getMessage()
                    );
                }
            }
        });
        return true;
    }
    catch (Exception exception)
    {
        Log.error("OpenMobile banner load failed: " + exception.getMessage());
        return false;
    }
}

public void AndroidThunkJava_CancelOpenMobileBannerAd(final long requestId)
{
    GameActivity.this.runOnUiThread(new Runnable()
