                            || !hasOpenMobileBannerSize(entry, desiredSize)
                        )
                    )
                    {
                        entry.notifyShownAfterLoad = true;
                        loadOpenMobileBannerView(entry, desiredSize);
                    }
                    else
                    {
                        attachOpenMobileBanner(entry);
                        nativeOpenMobileBannerAdShown(showRequestId);
                    }
                }
                catch (Exception exception)
                {
                    entry.notifyShownAfterLoad = false;
                    detachOpenMobileBanner(entry, true);
                    nativeOpenMobileBannerAdOperationFailed(
                        showRequestId,
                        "Banner could not be presented: " + exception.getMessage()
                    );
                }
            }
        });
        return true;
    }
    catch (Exception exception)
    {
        Log.error("OpenMobile banner show failed: " + exception.getMessage());
        return false;
    }
}

