gameActivityOnPauseAdditions.insert:
for (OpenMobileBannerEntry entry : openMobileBannerAds.values())
{
    if (entry.adView != null)
    {
        entry.adView.pause();
    }
}

gameActivityOnResumeAdditions.insert:
for (OpenMobileBannerEntry entry : openMobileBannerAds.values())
{
    if (entry.adView != null)
    {
        entry.adView.resume();
    }
    if (entry.container != null)
    {
        entry.container.requestApplyInsets();
    }
}

